/* Generated by tools/build_lines.py from picks/f.txt. Every line is from: NCERT XII (2026-27) Unit 4. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("f", "NCERT XII (2026-27) Unit 4", [{"sec": "Introduction","ids": [270],"t": "f-block: lanthanoids (14 after La) and actinoids (14 after Ac).","exc": false,"tab": false,"src": "d","page": 20,"o": "The f-block consists of the two series, lanthanoids (the fourteen elements following lanthanum) and actinoids (the fourteen elements following actinium)."},{"sec": "Introduction","ids": [271],"t": "La closely resembles the lanthanoids and is usually included; general symbol Ln.","exc": false,"tab": false,"src": "d","page": 20,"o": "Because lanthanum closely resembles the lanthanoids, it is usually included in any discussion of the lanthanoids for which the general symbol Ln is often used."},{"sec": "Introduction","ids": [273,274],"t": "Lanthanoids resemble each other more closely than members of any transition series; only one stable oxidation state.","exc": false,"tab": false,"src": "d","page": 20,"o": "The lanthanoids resemble one another more closely than do the members of ordinary transition elements in any series. They have only one stable oxidation state and their chemistry provides an excellent opportunity to examine the effect of small changes in size and nuclear charge along a series of otherwise similar elements."},{"sec": "Introduction","ids": [275,276],"t": "Actinoid chemistry is more complicated: wide range of oxidation states, plus radioactivity.","exc": false,"tab": false,"src": "d","page": 20,"o": "The chemistry of the actinoids is, on the other hand, much more complicated. The complication arises partly owing to the occurrence of a wide range of oxidation states in these elements and partly because their radioactivity creates special problems in their study."},{"sec": "Lanthanoids: configuration and size","ids": [278],"t": "Ln atoms: 6s^2 common, variable 4f occupancy.","exc": false,"tab": false,"src": "d","page": 21,"o": "It may be noted that atoms of these elements have electronic configuration with 6s^2 common but with variable occupancy of 4f level."},{"sec": "Lanthanoids: configuration and size","ids": [279],"t": "**All Ln^3+ (most stable state) are 4f^n**, n = 1–14.","exc": false,"tab": false,"src": "d","page": 21,"o": "However, the electronic configurations of all the tripositive ions (the most stable oxidation state of all the lanthanoids) are of the form 4f^n (n = 1 to 14 with increasing atomic number)."},{"sec": "Lanthanoids: configuration and size","ids": [280,281],"t": "Lanthanoid contraction: overall decrease in atomic and ionic radii La → Lu; big consequences for the third transition series.","exc": false,"tab": false,"src": "d","page": 21,"o": "The overall decrease in atomic and ionic radii from lanthanum to lutetium (the lanthanoid contraction) is a unique feature in the chemistry of the lanthanoids. It has far reaching consequences in the chemistry of the third transition series of the elements."},{"sec": "Lanthanoids: configuration and size","ids": [282],"t": "**Atomic radii decrease less regularly than M^3+ radii.**","exc": true,"tab": false,"src": "d","page": 21,"o": "The decrease in atomic radii (derived from the structures of metals) is not quite regular as it is regular in M^3+ ions."},{"sec": "Lanthanoids: configuration and size","ids": [283,284],"t": "Cause: imperfect shielding within the same sub-shell; 4f–4f shielding is worse than d–d.","exc": false,"tab": false,"src": "d","page": 21,"o": "This contraction is, of course, similar to that observed in an ordinary transition series and is attributed to the same cause, the imperfect shielding of one electron by another in the same sub-shell. However, the shielding of one 4f electron by another is less than one d electron by another with the increase in nuclear charge along the series."},{"sec": "Lanthanoids: configuration and size","ids": [285],"t": "Size decreases fairly regularly with Z.","exc": false,"tab": false,"src": "d","page": 21,"o": "There is fairly regular decrease in the sizes with increasing atomic number."},{"sec": "Lanthanoids: configuration and size","ids": [286],"t": "Cumulative effect: third transition series radii ≈ second series.","exc": false,"tab": false,"src": "d","page": 21,"o": "The cumulative effect of the contraction of the lanthanoid series, known as lanthanoid contraction, causes the radii of the members of the third transition series to be very similar to those of the corresponding members of the second series."},{"sec": "Lanthanoids: configuration and size","ids": [287],"t": "**Zr 160 pm ≈ Hf 159 pm: occur together in nature, hard to separate.**","exc": true,"tab": false,"src": "d","page": 21,"o": "The almost identical radii of Zr (160 pm) and Hf (159 pm), a consequence of the lanthanoid contraction, account for their occurrence together in nature and for the difficulty faced in their separation."},{"sec": "Lanthanoids: configuration and size","ids": [299],"t": "Table 4.9, configurations: La 5d^1 6s^2; Ce 4f^1 5d^1 6s^2; Gd 4f^7 5d^1 6s^2; Lu 4f^14 5d^1 6s^2; Eu 4f^7 6s^2; Yb 4f^14 6s^2.","exc": false,"tab": true,"src": "d","page": 22,"o": "Table 4.9, configurations: La 5d^1 6s^2; Ce 4f^1 5d^1 6s^2; Gd 4f^7 5d^1 6s^2; Lu 4f^14 5d^1 6s^2; Eu 4f^7 6s^2; Yb 4f^14 6s^2."},{"sec": "Lanthanoids: oxidation states","ids": [288,289],"t": "La(III) and Ln(III) dominate; +2 and +4 occasionally.","exc": false,"tab": false,"src": "d","page": 21,"o": "In the lanthanoids, La(III) and Ln(III) compounds are predominant species. However, occasionally +2 and +4 ions in solution or in solid compounds are also obtained."},{"sec": "Lanthanoids: oxidation states","ids": [290],"t": "Irregularity comes from extra stability of empty, half-filled or filled f subshell.","exc": false,"tab": false,"src": "d","page": 21,"o": "This irregularity (as in ionisation enthalpies) arises mainly from the extra stability of empty, half-filled or filled f subshell."},{"sec": "Lanthanoids: oxidation states","ids": [291],"t": "**Ce(IV): favoured by noble gas configuration, but a strong oxidant, reverts to +3.**","exc": true,"tab": false,"src": "d","page": 21,"o": "Thus, the formation of Ce(IV) is favoured by its noble gas configuration, but it is a strong oxidant reverting to the common +3 state."},{"sec": "Lanthanoids: oxidation states","ids": [292,293],"t": "**E°(Ce^4+/Ce^3+) = +1.74 V, should oxidise water, but very slow → Ce(IV) is a good analytical reagent.**","exc": true,"tab": false,"src": "d","page": 21,"o": "The E° value for Ce^4+/Ce^3+ is +1.74 V which suggests that it can oxidise water. However, the reaction rate is very slow and hence Ce(IV) is a good analytical reagent."},{"sec": "Lanthanoids: oxidation states","ids": [294],"t": "**Pr, Nd, Tb, Dy show +4 only in oxides MO2.**","exc": true,"tab": false,"src": "d","page": 21,"o": "Pr, Nd, Tb and Dy also exhibit +4 state but only in oxides, MO2."},{"sec": "Lanthanoids: oxidation states","ids": [294,295],"t": "**Eu^2+: loses two s electrons, f^7; strong reductant → +3.**","exc": true,"tab": false,"src": "d","page": 21,"o": "Eu^2+ is formed by losing the two s electrons and its f^7 configuration accounts for the formation of this ion. However, Eu^2+ is a strong reducing agent changing to the common +3 state."},{"sec": "Lanthanoids: oxidation states","ids": [296,297],"t": "**Yb^2+ (f^14) is a reductant. Tb(IV) (half-filled f) is an oxidant.**","exc": true,"tab": false,"src": "d","page": 21,"o": "Similarly Yb^2+ which has f^14 configuration is a reductant. Tb(IV) has half-filled f-orbitals and is an oxidant."},{"sec": "Lanthanoids: oxidation states","ids": [298],"t": "Sm behaves like Eu: both +2 and +3.","exc": false,"tab": false,"src": "d","page": 21,"o": "The behaviour of samarium is very much like europium, exhibiting both +2 and +3 oxidation states."},{"sec": "Lanthanoids: general characteristics","ids": [300,301],"t": "**Hardness increases with Z; Sm is steel hard.** m.p. 1000–1200 K, **but Sm 1623 K.**","exc": true,"tab": false,"src": "d","page": 22,"o": "The hardness increases with increasing atomic number, samarium being steel hard. Their melting points range between 1000 to 1200 K but samarium melts at 1623 K."},{"sec": "Lanthanoids: general characteristics","ids": [301],"t": "Typical metallic structure; good conductors of heat and electricity.","exc": false,"tab": false,"src": "d","page": 22,"o": "They have typical metallic structure and are good conductors of heat and electricity."},{"sec": "Lanthanoids: general characteristics","ids": [302],"t": "**Density and other properties change smoothly except Eu and Yb (sometimes Sm, Tm).**","exc": true,"tab": false,"src": "d","page": 22,"o": "Density and other properties change smoothly except for Eu and Yb and occasionally for Sm and Tm."},{"sec": "Lanthanoids: general characteristics","ids": [302,303],"t": "Many Ln^3+ coloured in solid and solution, due to f electrons.","exc": false,"tab": false,"src": "d","page": 22,"o": "Many trivalent lanthanoid ions are coloured both in the solid state and in aqueous solutions. Colour of these ions may be attributed to the presence of f electrons."},{"sec": "Lanthanoids: general characteristics","ids": [304,305],"t": "**La^3+ and Lu^3+ colourless; the rest coloured. Bands narrow (f–f excitation).**","exc": true,"tab": false,"src": "d","page": 22,"o": "Neither La^3+ nor Lu^3+ ion shows any colour but the rest do so. However, absorption bands are narrow, probably because of the excitation within f level."},{"sec": "Lanthanoids: general characteristics","ids": [306],"t": "**All Ln ions paramagnetic except f^0 (La^3+, Ce^4+) and f^14 (Yb^2+, Lu^3+).**","exc": true,"tab": false,"src": "d","page": 22,"o": "The lanthanoid ions other than the f^0 type (La^3+ and Ce^4+) and the f^14 type (Yb^2+ and Lu^3+) are all paramagnetic."},{"sec": "Lanthanoids: general characteristics","ids": [307],"t": "IE1 ≈ 600, IE2 ≈ 1200 kJ mol^–1, comparable with Ca.","exc": false,"tab": false,"src": "d","page": 22,"o": "The first ionisation enthalpies of the lanthanoids are around 600 kJ mol^–1, the second about 1200 kJ mol^–1 comparable with those of calcium."},{"sec": "Lanthanoids: general characteristics","ids": [308],"t": "IE3 trends: exchange enthalpy gives stability to empty, half-filled, filled f (as for 3d).","exc": false,"tab": false,"src": "d","page": 22,"o": "A detailed discussion of the variation of the third ionisation enthalpies indicates that the exchange enthalpy considerations (as in 3d orbitals of the first transition series), appear to impart a certain degree of stability to empty, half-filled and completely filled orbitals f level."},{"sec": "Lanthanoids: general characteristics","ids": [309],"t": "**Abnormally low IE3 for La, Gd, Lu.**","exc": true,"tab": false,"src": "d","page": 22,"o": "This is indicated from the abnormally low value of the third ionisation enthalpy of lanthanum, gadolinium and lutetium."},{"sec": "Lanthanoids: general characteristics","ids": [310],"t": "Early members reactive like Ca; later ones more like Al.","exc": false,"tab": false,"src": "d","page": 22,"o": "In their chemical behaviour, in general, the earlier members of the series are quite reactive similar to calcium but, with increasing atomic number, they behave more like aluminium."},{"sec": "Lanthanoids: general characteristics","ids": [311,312],"t": "**E°(Ln^3+/Ln) = –2.2 to –2.4 V, except Eu –2.0 V.**","exc": true,"tab": false,"src": "d","page": 22,"o": "Values for E° for the half-reaction: Ln^3+(aq) + 3e^– → Ln(s) are in the range of –2.2 to –2.4 V except for Eu for which the value is – 2.0 V."},{"sec": "Lanthanoids: general characteristics","ids": [312],"t": "Fig. 4.7, chemical reactions of the lanthanoids: with C at 2773 K → LnC2; heated with N2 → LnN; burns in O2 → Ln2O3; with H2O → Ln(OH)3 + H2; with acids → H2; heated with S → Ln2S3; with halogens → LnX3.","exc": false,"tab": true,"src": "d","page": 23,"o": "Fig. 4.7, chemical reactions of the lanthanoids: with C at 2773 K → LnC2; heated with N2 → LnN; burns in O2 → Ln2O3; with H2O → Ln(OH)3 + H2; with acids → H2; heated with S → Ln2S3; with halogens → LnX3."},{"sec": "Lanthanoids: general characteristics","ids": [313,314],"t": "Gentle heating in H2 → hydrides. With C: carbides Ln3C, Ln2C3, LnC2.","exc": false,"tab": false,"src": "d","page": 23,"o": "The metals combine with hydrogen when gently heated in the gas. The carbides, Ln3C, Ln2C3 and LnC2 are formed when the metals are heated with carbon."},{"sec": "Lanthanoids: general characteristics","ids": [315,316],"t": "Liberate H2 from dilute acids; burn in halogens → halides. Form M2O3 and M(OH)3.","exc": false,"tab": false,"src": "d","page": 23,"o": "They liberate hydrogen from dilute acids and burn in halogens to form halides. They form oxides M2O3 and hydroxides M(OH)3."},{"sec": "Lanthanoids: general characteristics","ids": [317,318],"t": "Hydroxides are definite compounds (not hydrated oxides), basic like alkaline earth ones.","exc": false,"tab": false,"src": "d","page": 23,"o": "The hydroxides are definite compounds, not just hydrated oxides. They are basic like alkaline earth metal oxides and hydroxides."},{"sec": "Lanthanoids: general characteristics","ids": [396],"t": "La and Ln: rather soft white metals.","exc": false,"tab": false,"src": "d","page": 26,"o": "Lanthanum and all the lanthanoids are rather soft white metals."},{"sec": "Lanthanoids: general characteristics","ids": [397],"t": "React easily with water → +3 ions.","exc": false,"tab": false,"src": "d","page": 26,"o": "They react easily with water to give solutions giving +3 ions."},{"sec": "Lanthanoids: uses","ids": [320],"t": "Main use: alloy steels for plates and pipes.","exc": false,"tab": false,"src": "d","page": 23,"o": "The best single use of the lanthanoids is for the production of alloy steels for plates and pipes."},{"sec": "Lanthanoids: uses","ids": [321],"t": "**Mischmetall: ~95% Ln + ~5% Fe + traces of S, C, Ca, Al.** Used in Mg alloys for bullets, shells, lighter flint.","exc": false,"tab": false,"src": "d","page": 23,"o": "A well known alloy is mischmetall which consists of a lanthanoid metal (~ 95%) and iron (~ 5%) and traces of S, C, Ca and Al. A good deal of mischmetall is used in Mg-based alloy to produce bullets, shell and lighter flint."},{"sec": "Lanthanoids: uses","ids": [322],"t": "Mixed Ln oxides: catalysts in petroleum cracking.","exc": false,"tab": false,"src": "d","page": 23,"o": "Mixed oxides of lanthanoids are employed as catalysts in petroleum cracking."},{"sec": "Lanthanoids: uses","ids": [323],"t": "Some Ln oxides: phosphors in TV screens.","exc": false,"tab": false,"src": "d","page": 23,"o": "Some individual Ln oxides are used as phosphors in television screens and similar fluorescing surfaces."},{"sec": "Actinoids","ids": [324],"t": "Actinoids: Th to Lr (14).","exc": false,"tab": false,"src": "d","page": 23,"o": "The actinoids include the fourteen elements from Th to Lr."},{"sec": "Actinoids","ids": [326],"t": "All radioactive; early ones long half-lives, later ones down to 3 min (Lr, Z = 103).","exc": false,"tab": false,"src": "d","page": 24,"o": "The actinoids are radioactive elements and the earlier members have relatively long half-lives, the latter ones have half-life values ranging from a day to 3 minutes for lawrencium (Z = 103)."},{"sec": "Actinoids","ids": [327],"t": "Later members made only in nanogram quantities.","exc": false,"tab": false,"src": "d","page": 24,"o": "The latter members could be prepared only in nanogram quantities."},{"sec": "Actinoids","ids": [329],"t": "Actinoids: 7s^2, variable 5f and 6d.","exc": false,"tab": false,"src": "d","page": 24,"o": "All the actinoids are believed to have the electronic configuration of 7s^2 and variable occupancy of the 5f and 6d subshells."},{"sec": "Actinoids","ids": [330],"t": "**14 electrons formally go into 5f, though not in Th; from Pa on, 5f fills, complete at 103.**","exc": true,"tab": false,"src": "d","page": 24,"o": "The fourteen electrons are formally added to 5f, though not in thorium (Z = 90) but from Pa onwards the 5f orbitals are complete at element 103."},{"sec": "Actinoids","ids": [331,332],"t": "Irregularities tied to stable f^0, f^7, f^14: **Am [Rn]5f^7 7s^2, Cm [Rn]5f^7 6d^1 7s^2.**","exc": false,"tab": false,"src": "d","page": 24,"o": "The irregularities in the electronic configurations of the actinoids, like those in the lanthanoids are related to the stabilities of the f^0, f^7 and f^14 occupancies of the 5f orbitals. Thus, the configurations of Am and Cm are [Rn] 5f^7 7s^2 and [Rn] 5f^7 6d^1 7s^2."},{"sec": "Actinoids","ids": [333],"t": "5f has the same angular part as 4f but is less buried → 5f electrons bond far more.","exc": false,"tab": false,"src": "d","page": 24,"o": "Although the 5f orbitals resemble the 4f orbitals in their angular part of the wave-function, they are not as buried as 4f orbitals and hence 5f electrons can participate in bonding to a far greater extent."},{"sec": "Actinoids","ids": [334],"t": "Lanthanoid trends generally seen in actinoids too.","exc": false,"tab": false,"src": "d","page": 24,"o": "The general trend in lanthanoids is observable in the actinoids as well."},{"sec": "Actinoids","ids": [335,336,337],"t": "**Actinoid contraction is greater per element than lanthanoid contraction** (poor 5f shielding).","exc": true,"tab": false,"src": "d","page": 24,"o": "There is a gradual decrease in the size of atoms or M^3+ ions across the series. This may be referred to as the actinoid contraction (like lanthanoid contraction). The contraction is, however, greater from element to element in this series resulting from poor shielding by 5f electrons."},{"sec": "Actinoids","ids": [338],"t": "Wider range of oxidation states: 5f, 6d, 7s comparable in energy.","exc": false,"tab": false,"src": "d","page": 24,"o": "There is a greater range of oxidation states, which is in part attributed to the fact that the 5f, 6d and 7s levels are of comparable energies."},{"sec": "Actinoids","ids": [340,341],"t": "Generally +3; first half often shows higher states.","exc": false,"tab": false,"src": "d","page": 24,"o": "The actinoids show in general +3 oxidation state. The elements, in the first half of the series frequently exhibit higher oxidation states."},{"sec": "Actinoids","ids": [342],"t": "**Max state: Th +4, Pa +5, U +6, Np +7, then decreases.**","exc": true,"tab": false,"src": "d","page": 24,"o": "For example, the maximum oxidation state increases from +4 in Th to +5, +6 and +7 respectively in Pa, U and Np but decreases in succeeding elements."},{"sec": "Actinoids","ids": [343,344],"t": "Like Ln, more +3 than +4 compounds; +3 and +4 ions tend to hydrolyse.","exc": false,"tab": false,"src": "d","page": 24,"o": "The actinoids resemble the lanthanoids in having more compounds in +3 state than in the +4 state. However, +3 and +4 ions tend to hydrolyse."},{"sec": "Actinoids","ids": [345,346],"t": "All silvery, but varied structures (metallic radii far more irregular than Ln).","exc": false,"tab": false,"src": "d","page": 24,"o": "The actinoid metals are all silvery in appearance but display a variety of structures. The structural variability is obtained due to irregularities in metallic radii which are far greater than in lanthanoids."},{"sec": "Actinoids","ids": [347,348],"t": "Highly reactive, especially finely divided; boiling water → oxide + hydride mixture; combine with most non-metals at moderate temperature.","exc": false,"tab": false,"src": "d","page": 25,"o": "The actinoids are highly reactive metals, especially when finely divided. The action of boiling water on them, for example, gives a mixture of oxide and hydride and combination with most non metals takes place at moderate temperatures."},{"sec": "Actinoids","ids": [349],"t": "**HCl attacks all; HNO3 barely (protective oxide layer); alkalies no action.**","exc": true,"tab": false,"src": "d","page": 25,"o": "Hydrochloric acid attacks all metals but most are slightly affected by nitric acid owing to the formation of protective oxide layers; alkalies have no action."},{"sec": "Actinoids","ids": [350,351],"t": "Magnetism more complex than Ln; susceptibility vs unpaired 5f roughly parallels Ln, but Ln values are higher.","exc": false,"tab": false,"src": "d","page": 25,"o": "The magnetic properties of the actinoids are more complex than those of the lanthanoids. Although the variation in the magnetic susceptibility of the actinoids with the number of unpaired 5f electrons is roughly parallel to the corresponding results for the lanthanoids, the latter have higher values."},{"sec": "Actinoids","ids": [352],"t": "**IE of early actinoids lower than early lanthanoids.**","exc": true,"tab": false,"src": "d","page": 25,"o": "It is evident from the behaviour of the actinoids that the ionisation enthalpies of the early actinoids, though not accurately known, but are lower than for the early lanthanoids."},{"sec": "Actinoids","ids": [353,354,355],"t": "Reason: early 5f penetrates less, so 5f electrons are better shielded than 4f → held less firmly, available for bonding.","exc": false,"tab": false,"src": "d","page": 25,"o": "This is quite reasonable since it is to be expected that when 5f orbitals are beginning to be occupied, they will penetrate less into the inner core of electrons. The 5f electrons, will therefore, be more effectively shielded from the nuclear charge than the 4f electrons of the corresponding lanthanoids. Because the outer electrons are less firmly held, they are available for bonding in the actinoids."},{"sec": "Actinoids","ids": [356],"t": "Lanthanoid-like behaviour only appears in the second half of the actinoids.","exc": false,"tab": false,"src": "d","page": 25,"o": "A comparison of the actinoids with the lanthanoids, with respect to different characteristics as discussed above, reveals that behaviour similar to that of the lanthanoids is not evident until the second half of the actinoid series."},{"sec": "Actinoids","ids": [357],"t": "Even early actinoids resemble each other closely, with gradual variation in properties not involving oxidation-state change.","exc": false,"tab": false,"src": "d","page": 25,"o": "However, even the early actinoids resemble the lanthanoids in showing close similarities with each other and in gradual variation in properties which do not entail change in oxidation state."},{"sec": "Actinoids","ids": [358,359],"t": "Both contractions affect sizes of following elements; lanthanoid contraction matters more (post-actinoid chemistry little known).","exc": false,"tab": false,"src": "d","page": 25,"o": "The lanthanoid and actinoid contractions, have extended effects on the sizes, and therefore, the properties of the elements succeeding them in their respective periods. The lanthanoid contraction is more important because the chemistry of elements succeeding the actinoids are much less known at the present time."}]);
})();
